"""Summarize workflow tables without writing to the node."""
import argparse
from datetime import datetime, timedelta, timezone
import json
from pathlib import Path
import re

EVERY = re.compile(r"[1-9][0-9]*[rsmhd]\Z")
CODE = re.compile(r"[+-]?[0-9]+\Z")
SECONDS = {"s": 1, "m": 60, "h": 3600, "d": 86400}
REQUIRED = {"routines": ("name", "every", "last_time", "last_code"),
            "schedule": ("name", "at", "claimed")}


def reject_constant(value):
    raise ValueError("non-finite JSON constant: " + value)


def read_table(node, table):
    try:
        with (node / "wf" / (table + ".json")).open(encoding="utf-8") as stream:
            data = json.load(stream, parse_constant=reject_constant)
    except FileNotFoundError:
        return [], []
    except (OSError, UnicodeError, ValueError, RecursionError):
        data = None
    if (not isinstance(data, dict) or data.get("contract") != "wf-table/1"
            or not isinstance(data.get("columns"), list)
            or not all(isinstance(column, str) for column in data["columns"])
            or not isinstance(data.get("rows"), list)):
        return [], [{"table": table, "row": None, "why": "bad_table"}]
    return data["rows"], []


def timestamp(value, now):
    parsed = datetime.fromisoformat(value)
    return parsed.replace(tzinfo=now.tzinfo) if parsed.tzinfo is None else parsed


def routine(row, now):
    every = row["every"]
    if not EVERY.fullmatch(every):
        raise ValueError("invalid interval")
    raw_code = row["last_code"]
    if raw_code == "":
        code = None
    elif raw_code == "running":
        code = "running"
    elif CODE.fullmatch(raw_code):
        code = int(raw_code)
    else:
        raise ValueError("invalid code")
    raw_time = row["last_time"]
    last = timestamp(raw_time, now) if raw_time else None
    following = last + timedelta(seconds=int(every[:-1]) * SECONDS[every[-1]]) if last and every[-1] != "r" else None
    if code == "running":
        state = "running"
    elif last is None:
        state = "never"
    elif isinstance(code, int) and code != 0:
        state = "failed"
    elif following is not None and now >= following:
        state = "overdue"
    else:
        state = "ok"
    rendered = following.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ") if following else None
    return {"name": row["name"], "every": every, "last_time": raw_time or None,
            "last_code": code, "state": state, "next": rendered}


def schedule(row, now):
    at = timestamp(row["at"], now)
    state = "interrupted" if row["claimed"] else "due" if at <= now else "pending"
    return {"name": row["name"], "at": row["at"], "state": state}


def summarize(node, now):
    output = {"v": 1, "routines": [], "schedule": [],
              "counts": {"routines": dict.fromkeys(("running", "never", "failed", "overdue", "ok"), 0),
                         "schedule": dict.fromkeys(("interrupted", "due", "pending"), 0)},
              "bad": []}
    for table in ("routines", "schedule"):
        rows, errors = read_table(node, table)
        output["bad"].extend(errors)
        seen = set()
        for index, row in enumerate(rows):
            name = row.get("name") if isinstance(row, dict) else None
            if isinstance(name, str) and name:
                duplicate = name in seen
                seen.add(name)
            else:
                duplicate = False
            why = "dup_name" if duplicate else "bad_row"
            if (duplicate or not isinstance(row, dict)
                    or not all(isinstance(value, str) for value in row.values())
                    or not all(key in row for key in REQUIRED[table])
                    or not isinstance(name, str) or not name):
                output["bad"].append({"table": table, "row": index, "why": why})
                continue
            try:
                item = routine(row, now) if table == "routines" else schedule(row, now)
            except (ValueError, OverflowError):
                output["bad"].append({"table": table, "row": index, "why": "bad_row"})
                continue
            output[table].append(item)
            output["counts"][table][item["state"]] += 1
        output[table].sort(key=lambda item: item["name"])
    output["bad"].sort(key=lambda item: (item["table"], -1 if item["row"] is None else item["row"], item["why"]))
    return output


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only workflow runs summary")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO timestamp with a timezone")
    if now.tzinfo is None:
        parser.error("--now must have a timezone")
    print(json.dumps(summarize(args.folder, now), ensure_ascii=True, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
